Plan, no edits made.

**JSON prints `buildRows()` straight, so it carries `owner` and `slow` too.** The table drops those two on purpose. `format.js:3` says anything needing whole rows goes back to `buildRows()`, not the table. So "same data" means the same rows, not the same four columns.

```js
// src/cli.js
const USAGE = 'usage: cli.js report [--json]';

function main(argv) {
  if (argv[0] !== 'report') { process.stderr.write(USAGE + '\n'); return 1; }
  const rest = argv.slice(1);
  const json = rest.includes('--json');
  if (rest.some((a) => a !== '--json')) { process.stderr.write(USAGE + '\n'); return 1; }
  const rows = buildRows();
  process.stdout.write((json ? JSON.stringify(rows, null, 2) : toTable(rows)) + '\n');
  return 0;
}
```

`format.js` and `report.js` stay untouched. Sort order holds in both. Say the word and I write it.
